package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {





    @Test
    public void testCreateNumber_HexInteger() throws NumberFormatException {
        // Hex digits <= 8 -> Integer
        assertTrue(NumberUtils.createNumber("0x12345678") instanceof Integer);
        // Hex digits > 8 and <= 16 -> Long
        assertTrue(NumberUtils.createNumber("0x123456789ABCDEF") instanceof Long);
        // Hex digits > 16 -> BigInteger
        assertTrue(NumberUtils.createNumber("0x123456789ABCDEF012345678") instanceof BigInteger);
        // Testing other prefixes
        assertTrue(NumberUtils.createNumber("0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("#123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-#123") instanceof Integer);
    }













    // Helper to handle JUnit 4 lack of assertThrows for exceptions with specific messages
    private void assertThrows(Class<? extends Throwable> expectedType, Runnable runnable) {
        try {
            runnable.run();
            fail("Expected exception " + expectedType.getName() + " but none was thrown");
        } catch (Throwable t) {
            if (!expectedType.isInstance(t)) {
                fail("Expected exception " + expectedType.getName() + " but caught " + t.getClass().getName());
            }
        }
    }
}

