        // Long suffix
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        // BigInteger via Long suffix overflow
        // Note: This depends on implementation of createLong/createBigInteger
        // Assuming "9223372036854775808L" triggers the catch block in the code
        assertTrue(NumberUtils.createNumber("9223372036854775808L") instanceof BigInteger);

        // Float suffix
        assertTrue(NumberUtils.createNumber("123.45F") instanceof Float);
        assertTrue(NumberUtils.createNumber("123.45f") instanceof Float);

        // Double suffix
        assertTrue(NumberUtils.createNumber("123.45D") instanceof Double);
        assertTrue(NumberUtils.createNumber("123.45d") instanceof Double);
    }







